function iom_snapshot(){ $a=['groups'=>ipl_groups(),'cycle'=>get_option('instapass_claude_credit_cycle'),'products'=>[]];foreach(wc_get_products(['limit'=>-1,'status'=>['publish','draft','private','pending']]) as $p){$props=$p->get_data();unset($props['id'],$props['meta_data']);foreach($props as $k=>$v)if($v instanceof DateTimeInterface)$props[$k]=$v->getTimestamp();$meta=[];foreach($p->get_meta_data() as $v){$x=$v->get_data();$meta[$x['key']]=$x['value'];}$a['products'][$p->get_id()]=['props'=>$props,'meta'=>$meta,'hash'=>hash('sha256',wp_json_encode($p->get_data()))];}return $a;}
